// Hand-added regression test for the OAuth scope fix (GH servosity/msp-skills#7).
// NOT generated by the Printing Press; guards that the client auto-mint path
// (used by halopsa-mcp during requests) sends the configured OAuth2 scope.

package client

import (
	"io"
	"net/http"
	"net/http/httptest"
	"net/url"
	"path/filepath"
	"testing"
	"time"

	"halopsa-pp-cli/internal/config"
)

func TestClientMintClientCredentialsSendsScope(t *testing.T) {
	var gotForm url.Values
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		gotForm, _ = url.ParseQuery(string(body))
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"access_token":"tok","expires_in":3600}`))
	}))
	defer srv.Close()

	cfg := &config.Config{
		TokenURL:     srv.URL,
		HalopsaScope: "all",
		Path:         filepath.Join(t.TempDir(), "config.toml"),
	}
	c := New(cfg, 10*time.Second, 0)

	if err := c.mintClientCredentials("cid", "csecret"); err != nil {
		t.Fatalf("mintClientCredentials: %v", err)
	}
	if gotForm.Get("scope") != "all" {
		t.Fatalf("scope = %q, want %q (form=%v)", gotForm.Get("scope"), "all", gotForm)
	}
}
